import { ALLOWLIST, USER_AGENT, VERSION, isAllowed } from './allowlist.js';

/**
 * Request handler for the Zurich maps Workers site.
 *
 * The Worker only answers `/api/*` (see `assets.run_worker_first` in
 * wrangler.jsonc); every other request is served directly from the static asset
 * directory `public/`.
 *
 * Why a proxy at all?
 *  - swisstopo SearchServer (`api3.geo.admin.ch`) sends CORS `*`, but routing it
 *    through the Worker gives us one stable origin, a bounded query and an edge
 *    cache in front of a public service we want to call politely.
 *  - e-rara IIIF images/manifests normally allow CORS; `/api/fetch` is a
 *    *fallback* for clients/networks where the direct call fails. It is limited
 *    to a literal allowlist of hosts, so it cannot be used as an open proxy.
 *
 * No credentials are required or read by this Worker.
 */

function json(body, init = {}) {
  return new Response(JSON.stringify(body, null, 1), {
    ...init,
    headers: { 'content-type': 'application/json; charset=utf-8', ...(init.headers || {}) },
  });
}

async function upstream(url, { accept = '*/*', timeoutMs = 8000 } = {}) {
  return fetch(url, {
    headers: { 'user-agent': USER_AGENT, accept },
    signal: AbortSignal.timeout(timeoutMs),
    redirect: 'follow',
  });
}

/** Read a JSON file that ships with the site through the assets binding. */
async function asset(env, path, request) {
  const url = new URL(request.url);
  url.pathname = path;
  url.search = '';
  return env.ASSETS.fetch(new Request(url.toString(), { method: 'GET' }));
}

async function cachedJson(request, ctx, build, maxAge) {
  const cache = caches.default;
  const cacheKey = new Request(new URL(request.url).toString(), { method: 'GET' });
  const hit = await cache.match(cacheKey);
  if (hit) return hit;
  const body = await build();
  const res = json(body, { headers: { 'cache-control': `public, max-age=${maxAge}` } });
  ctx.waitUntil(cache.put(cacheKey, res.clone()));
  return res;
}

/** GET /api/health — liveness plus the upstreams this Worker may contact. */
function health(request) {
  return json({
    ok: true,
    version: VERSION,
    runtime: 'cloudflare-workers',
    upstreams: ALLOWLIST.map((r) => r.host),
    endpoints: ['/api/health', '/api/records', '/api/layers', '/api/sources', '/api/search/places', '/api/fetch'],
    time: new Date().toISOString(),
  });
}

/** GET /api/search/places?q=&limit= — swisstopo SearchServer (type=locations). */
async function searchPlaces(request, ctx) {
  const url = new URL(request.url);
  const q = (url.searchParams.get('q') || '').trim();
  const limit = Math.min(Math.max(Number(url.searchParams.get('limit') || 8), 1), 20);
  if (q.length < 2 || q.length > 120) {
    return json({ error: 'query_too_short', detail: 'q must be 2..120 characters', results: [] }, { status: 400 });
  }
  return cachedJson(
    request,
    ctx,
    async () => {
      const target = new URL('https://api3.geo.admin.ch/rest/services/api/SearchServer');
      target.searchParams.set('searchText', q);
      target.searchParams.set('type', 'locations');
      target.searchParams.set('sr', '4326'); // WGS84 lon/lat
      target.searchParams.set('limit', String(limit));
      const res = await upstream(target.toString(), { accept: 'application/json' });
      if (!res.ok) {
        return { results: [], upstreamStatus: res.status, note: 'swisstopo SearchServer error' };
      }
      const data = await res.json();
      const results = (data.results || []).map((r) => {
        const a = r.attrs || {};
        const box = (a.geom_st_box2d || 'BOX(0 0,0 0)').match(/BOX\(([-\d.]+) ([-\d.]+),([-\d.]+) ([-\d.]+)\)/);
        return {
          label: String(a.label || '').replace(/<[^>]*>/g, ''),
          origin: a.origin || null,
          lat: typeof a.lat === 'number' ? a.lat : null,
          lon: typeof a.lon === 'number' ? a.lon : null,
          layerBodId: a.layerBodId || null,
          // upstream `zoomlevel` is a bitfield/uint32 for some origins; only pass sane values on
          zoom: Number.isFinite(a.zoomlevel) && a.zoomlevel > 0 && a.zoomlevel <= 20 ? a.zoomlevel : null,
          bbox: box ? { west: Number(box[1]), south: Number(box[2]), east: Number(box[3]), north: Number(box[4]) } : null,
        };
      });
      return { results, source: 'swisstopo SearchServer', attribution: '© swisstopo' };
    },
    300,
  );
}

/** GET /api/fetch?url= — allowlisted pass-through with a 1 h edge cache. */
async function fetchUpstream(request, ctx) {
  const url = new URL(request.url);
  const raw = url.searchParams.get('url');
  if (!raw) return json({ error: 'missing_url' }, { status: 400 });
  let target;
  try {
    target = new URL(raw);
  } catch {
    return json({ error: 'invalid_url' }, { status: 400 });
  }
  if (!isAllowed(target)) {
    return json({ error: 'host_not_allowed', host: target.hostname, allowlist: ALLOWLIST.map((r) => r.host) }, { status: 403 });
  }
  const cache = caches.default;
  const cacheKey = new Request(`${url.origin}/api/fetch?url=${encodeURIComponent(target.toString())}`, { method: 'GET' });
  const hit = await cache.match(cacheKey);
  if (hit) return hit;
  let res;
  try {
    res = await upstream(target.toString(), { accept: url.searchParams.get('accept') || '*/*' });
  } catch (err) {
    return json({ error: 'upstream_unreachable', detail: String(err && err.message) }, { status: 502 });
  }
  if (!res.ok) return json({ error: 'upstream_error', status: res.status }, { status: 502 });
  const type = res.headers.get('content-type') || 'application/octet-stream';
  const out = new Response(res.body, {
    status: 200,
    headers: {
      'content-type': type,
      'cache-control': 'public, max-age=3600',
      'access-control-allow-origin': '*',
      'x-proxied-from': target.hostname,
    },
  });
  ctx.waitUntil(cache.put(cacheKey, out.clone()));
  return out;
}

export default {
  /**
   * @param {Request} request
   * @param {{ ASSETS: { fetch: (r: Request) => Promise<Response> } }} env
   * @param {{ waitUntil: (p: Promise<unknown>) => void }} ctx
   */
  async fetch(request, env, ctx) {
    const url = new URL(request.url);

    if (url.pathname.startsWith('/api/')) {
      if (request.method !== 'GET' && request.method !== 'HEAD') {
        return json({ error: 'method_not_allowed' }, { status: 405, headers: { allow: 'GET, HEAD' } });
      }
      try {
        switch (url.pathname) {
          case '/api/health':
            return health(request);
          case '/api/search/places':
            return await searchPlaces(request, ctx);
          case '/api/fetch':
            return await fetchUpstream(request, ctx);
          case '/api/records':
          case '/api/layers':
          case '/api/sources': {
            const path = { '/api/records': '/data/records.json', '/api/layers': '/data/overlays.json', '/api/sources': '/data/sources.json' }[
              url.pathname
            ];
            const res = await asset(env, path, request);
            if (!res.ok) return json({ error: 'asset_missing', path }, { status: 500 });
            return new Response(res.body, {
              status: 200,
              headers: {
                'content-type': 'application/json; charset=utf-8',
                'cache-control': 'public, max-age=300',
                'access-control-allow-origin': '*',
              },
            });
          }
          default:
            return json({ error: 'not_found', path: url.pathname }, { status: 404 });
        }
      } catch (err) {
        return json({ error: 'worker_error', detail: String(err && err.message) }, { status: 500 });
      }
    }

    // Defensive: if run_worker_first is widened, still behave like a static host.
    if (env && env.ASSETS) return env.ASSETS.fetch(request);
    return new Response('Not found', { status: 404, headers: { 'content-type': 'text/plain; charset=utf-8' } });
  },
};

// NOTE: only `default` may be exported from a Workers entrypoint. workerd rejects
// non-function named exports at startup ("Incorrect type for map entry 'VERSION'"
// is the exact failure), so constants stay module-private and are exercised through
// the HTTP surface (see tests/worker.test.mjs → /api/health).

/**
 * Interactive map: a dependency-free slippy map (Web Mercator, 256 px tiles)
 * fed by swisstopo WMTS geoservices, plus historical comparison layers.
 *
 * Deliberately small and explicit instead of vendoring a whole map library:
 *   - base: Landeskarte (swisstopo `ch.swisstopo.pixelkarte-farbe`)
 *   - comparison: any layer from /data/overlays.json (Zeitreise, Dufour, Siegfried, …)
 *   - markers: records with a documented point/bbox (public/app/records.js)
 *
 * Keyboard: the container is focusable; arrows pan, +/- zoom, Home = Zürich,
 * End = fit results. The result list is the equivalent accessible interface.
 *
 * Coordination with the result list: hovering/focusing a marker shows a small
 * preview card and emits `record:preview`, so the matching row in the list
 * highlights (and the other way round) — the OldMapsOnline list/map behaviour.
 */

import { debounce, el, formatYearRange, qs } from './dom.js';
import { recordCenter } from './records.js';
import { parsePoint, sanitisePoint } from './store.js';

const TILE = 256;

/**
 * Base maps (Grundkarten): the documented swisstopo WMTS layers a visitor can
 * choose from. Tiles are public geoservices and carry
 * `Access-Control-Allow-Origin: *`.
 *
 * Verified against the official capabilities document
 * https://wmts.geo.admin.ch/EPSG/3857/1.0.0/WMTSCapabilities.xml (fetched
 * 2026-10-19): all three layers are published there with style id = layer id,
 * `image/jpeg` tiles and the 3857_19 / 3857_20 tile matrix sets, so the same
 * 256 px `{TileMatrix}/{TileCol}/{TileRow}` template serves each of them.
 * `maxZoom: 18` is the deepest matrix every one of them has (the store clamps
 * the zoom to 18 as well), so no request can ask for a missing tile.
 *
 * `key` is what the URL carries (`?base=grau`): short, stable, printable.
 */
export const BASE_LAYERS = Object.freeze([
  {
    key: 'farbe',
    id: 'ch.swisstopo.pixelkarte-farbe',
    title: 'Landeskarte (farbig)',
    chip: 'farbig',
    hint: 'Die farbige Landeskarte von swisstopo – die gewohnte Kartenansicht.',
    maxZoom: 18,
    urlTemplate:
      'https://wmts.geo.admin.ch/1.0.0/ch.swisstopo.pixelkarte-farbe/default/current/3857/{TileMatrix}/{TileCol}/{TileRow}.jpeg',
    attribution: '© swisstopo – Landeskarte (farbig)',
  },
  {
    key: 'grau',
    id: 'ch.swisstopo.pixelkarte-grau',
    title: 'Landeskarte (grau)',
    chip: 'grau',
    hint: 'Die graue Landeskarte: ein ruhiger Hintergrund für Markierungen, Ausschnitte und historische Ebenen.',
    maxZoom: 18,
    urlTemplate:
      'https://wmts.geo.admin.ch/1.0.0/ch.swisstopo.pixelkarte-grau/default/current/3857/{TileMatrix}/{TileCol}/{TileRow}.jpeg',
    attribution: '© swisstopo – Landeskarte (grau)',
  },
  {
    key: 'luftbild',
    id: 'ch.swisstopo.swissimage',
    title: 'SWISSIMAGE (Luftbild)',
    chip: 'Luftbild',
    hint: 'Das aktuelle Luftbild von swisstopo (SWISSIMAGE) – gut zum Vergleich mit alten Karten.',
    maxZoom: 18,
    urlTemplate:
      'https://wmts.geo.admin.ch/1.0.0/ch.swisstopo.swissimage/default/current/3857/{TileMatrix}/{TileCol}/{TileRow}.jpeg',
    attribution: '© swisstopo – SWISSIMAGE',
  },
]);

/** The base map of a fresh visit — also the fallback for an unknown key. */
export const DEFAULT_BASE = BASE_LAYERS[0];

/** Kept for callers that only need the default layer. */
export const BASE_LAYER = DEFAULT_BASE;

/**
 * Resolve a `?base=` key to a layer. An empty or unknown key yields the default:
 * never an error, never a guessed layer.
 */
export function baseLayerFor(key) {
  const wanted = String(key ?? '')
    .trim()
    .toLowerCase();
  return BASE_LAYERS.find((layer) => layer.key === wanted) ?? DEFAULT_BASE;
}

export const ZURICH = { lat: 47.3769, lon: 8.5417, zoom: 12 };
export const SWITZERLAND = { west: 5.140242, east: 11.47757, south: 45.398181, north: 48.230651 };

export const lonToTileX = (lon, z) => ((lon + 180) / 360) * 2 ** z;
export const latToTileY = (lat, z) => {
  const s = Math.sin((Math.max(-85.05112878, Math.min(85.05112878, lat)) * Math.PI) / 180);
  return (0.5 - Math.log((1 + s) / (1 - s)) / (4 * Math.PI)) * 2 ** z;
};
export const tileXToLon = (x, z) => (x / 2 ** z) * 360 - 180;
export const tileYToLat = (y, z) => {
  const n = Math.PI - (2 * Math.PI * y) / 2 ** z;
  return (180 / Math.PI) * Math.atan(0.5 * (Math.exp(n) - Math.exp(-n)));
};

/** Tile URL from a WMTS template with {TileMatrix}/{TileCol}/{TileRow}/{Time}. */
export function tileUrl(template, { z, x, y, time }) {
  return template
    .replace('{TileMatrix}', String(z))
    .replace('{TileCol}', String(x))
    .replace('{TileRow}', String(y))
    .replace('{Time}', encodeURIComponent(time ?? 'current'));
}

/** Grid size (px) used to group markers that would overlap at the current zoom. */
export const CLUSTER_CELL = 56;

/**
 * Deepest zoom the base layers publish (see BASE_LAYERS) — and the zoom the
 * store clamps to. A cluster at this zoom cannot be split any further by
 * zooming, so it must offer another way to its records.
 */
export const MAX_ZOOM = 18;

/**
 * Group already projected pixel points into grid cells.
 *
 * Points are global pixel coordinates at one zoom level, so a cell key is
 * stable while panning: a cluster keeps its members and its count instead of
 * changing with the viewport. Pure, therefore unit-tested.
 */
export function clusterByCell(points, cellPx = CLUSTER_CELL) {
  const cells = new Map();
  for (const point of points ?? []) {
    const key = `${Math.floor(point.x / cellPx)}:${Math.floor(point.y / cellPx)}`;
    let cell = cells.get(key);
    if (!cell) {
      cell = { key, x: 0, y: 0, count: 0, members: [] };
      cells.set(key, cell);
    }
    cell.x += point.x;
    cell.y += point.y;
    cell.count += 1;
    cell.members.push(point);
  }
  return [...cells.values()].map((cell) => ({ ...cell, x: cell.x / cell.count, y: cell.y / cell.count }));
}

/**
 * The documented anchor of a record as a comparable key (6 decimals ≈ 0.1 m).
 * Returns `''` for a record without any published point or extent.
 */
export function clusterAnchorKey(record) {
  const center = recordCenter(record);
  if (!center) return '';
  return `${Number(center.lat).toFixed(6)}:${Number(center.lon).toFixed(6)}`;
}

/**
 * Can zooming further separate this cluster into single markers?
 *
 * Usually yes: the cell shrinks with the zoom. Two cases provably cannot be
 * split, and both must not pretend otherwise:
 *
 *   - **point piles** — every member carries the *same* documented anchor (six
 *     Zürich Stadtpläne sit on 47.358330 / 8.533340 in the catalogue), so the
 *     pins keep sharing a cell at every zoom level;
 *   - the map is already at `MAX_ZOOM`.
 *
 * Pure, therefore unit-tested; `renderMarkers` uses it to decide whether a
 * cluster click zooms (the OldMapsOnline gesture) or opens the list of the
 * records behind the number.
 */
export function clusterCanSplit(members, zoom, maxZoom = MAX_ZOOM) {
  const list = [...(members ?? [])].filter((member) => member?.record);
  if (list.length < 2) return true;
  if (Math.round(Number(zoom) || 0) >= Number(maxZoom)) return false;
  const keys = list.map((member) => clusterAnchorKey(member.record));
  // An anchor that cannot be computed is never proof of a shared point.
  if (keys.some((key) => key === '')) return true;
  return new Set(keys).size > 1;
}

/**
 * The records behind a cluster, oldest first (then by title) — the order the
 * “Karten an diesem Punkt” list shows them in, so several editions of one place
 * read as a sequence instead of as an arbitrary set.
 */
export function clusterRecords(members) {
  return [...(members ?? [])]
    .map((member) => member?.record)
    .filter(Boolean)
    .sort(
      (a, b) =>
        Number(a.yearStart ?? 0) - Number(b.yearStart ?? 0) ||
        String(a.title ?? '').localeCompare(String(b.title ?? ''), 'de'),
    );
}

/**
 * Pixel rectangles for the documented extents of `records`, relative to a map
 * container of `size` ({ width, height }) showing `view` ({ lat, lon, zoom }).
 *
 * This is the geometry behind the “Ausschnitte” layer: it answers “which part of
 * the map does each filtered record actually claim to cover?”. Only the
 * documented extent is used — never an inferred or guessed footprint — and
 * records without an extent are counted (`withExtent`) so the caller can say so
 * honestly. Rectangles outside the visible box (plus a margin) are dropped, so
 * panning a large result set stays cheap.
 *
 * Records that share the same extent (the swisstopo series sheets all state
 * Switzerland) become ONE rectangle carrying every member id: drawing 27
 * identical outlines would only darken the map. Pure (no DOM), so it is unit
 * tested; `rects` is sorted largest-first and the caller paints in reverse so
 * more specific (smaller) footprints stay readable on top of country-wide ones.
 */
export function extentRects(records, view, size, { margin = 64, max = 500 } = {}) {
  const zoom = Math.max(2, Math.min(18, Math.round(Number(view?.zoom) || 12)));
  const width = Math.max(1, Number(size?.width) || 1);
  const height = Math.max(1, Number(size?.height) || 1);

