import json, math, sys

def ring_area(r):
    s=0
    for (x1,y1),(x2,y2) in zip(r,r[1:]):
        s += x1*y2-x2*y1
    return abs(s)/2

def perp(p,a,b):
    x,y=p; x1,y1=a; x2,y2=b
    dx,dy=x2-x1,y2-y1
    if dx==dy==0: return math.hypot(x-x1,y-y1)
    t=((x-x1)*dx+(y-y1)*dy)/(dx*dx+dy*dy)
    if t<0: return math.hypot(x-x1,y-y1)
    if t>1: return math.hypot(x-x2,y-y2)
    return math.hypot(x-(x1+t*dx), y-(y1+t*dy))

def dp(pts,tol):
    if len(pts)<3: return pts
    keep=[False]*len(pts); keep[0]=keep[-1]=True
    stack=[(0,len(pts)-1)]
    while stack:
        i,j=stack.pop()
        if j<=i+1: continue
        dmax=0; idx=None
        for k in range(i+1,j):
            d=perp(pts[k],pts[i],pts[j])
            if d>dmax: dmax=d; idx=k
        if dmax>tol:
            keep[idx]=True; stack.append((i,idx)); stack.append((idx,j))
    return [p for p,k in zip(pts,keep) if k]

def simplify_ring(r,tol,minarea):
    if len(r)>3 and r[0]==r[-1]: closed=True; body=r[:-1]
    else: closed=False; body=r
    if len(body)<3: return None
    # radial dedupe
    out=[]
    for p in body:
        if not out or abs(p[0]-out[-1][0])>1e-9 or abs(p[1]-out[-1][1])>1e-9: out.append(p)
    if len(out)<3: return None
    # ensure closed for DP? keep first=last
    closed_ring=out+[out[0]]
    simp=dp(closed_ring,tol)[:-1]
    if len(simp)<3: simp=out[:3]
    if ring_area(simp+[simp[0]])<minarea: return None
    simp=[(round(x,2),round(y,2)) for x,y in simp]
    # dedupe after rounding
    q=[]
    for p in simp:
        if not q or p!=q[-1]: q.append(p)
    if len(q)<3: return None
    q.append(q[0])
    if ring_area(q)<minarea: return None
    return q

def process(src,dst,tol=0.02,minarea=0.001):
    d=json.load(open(src)); out=[]; npts=0
    for feat in d['features']:
        p=feat['properties']; name=(p.get('NAME') or '').strip()
        if not name: continue
        geom=feat['geometry']; polys=geom['coordinates'] if geom['type']=='MultiPolygon' else [geom['coordinates']]
        newpolys=[]
        for poly in polys:
            rings=[]
            for i,r in enumerate(poly):
                sr=simplify_ring(r,tol,minarea if i==0 else minarea/4)
                if sr: rings.append(sr)
            if rings: newpolys.append(rings)
        if not newpolys: continue
        g={'type':'MultiPolygon','coordinates':newpolys}
        out.append({'type':'Feature','properties':{'name':name},'geometry':g})
        npts+=sum(len(r) for poly in newpolys for r in poly)
    outj={'type':'FeatureCollection','features':out}
    js=json.dumps(outj,separators=(',',':'))
