#!/usr/bin/env node
/**
 * Reproducible pipeline for the History / Borders dataset.
 *
 * Primary source: André Ourednik's historical-basemaps repository
 *   https://github.com/aourednik/historical-basemaps
 * The repository publishes GeoJSON snapshots, a year index and a GPL-3.0
 * licence. We pin one upstream commit, fetch every snapshot in its index and
 * produce a smaller, clickable copy for the Workers site. No aggregator or
 * private endpoint is involved.
 *
 *   node scripts/fetch-history.mjs            # download (cached) + rebuild
 *   node scripts/fetch-history.mjs --offline  # rebuild from .cache/history
 *
 * Outputs (committed, so the Cloudflare build needs no network):
 *   public/data/history/index.json                  years, licence, provenance
 *   public/data/history/snapshots/<year>.json       simplified FeatureCollection
 *   public/data/history/LICENSE-GPL-3.0.txt         upstream licence verbatim
 *   public/data/history/SOURCE.md                  human-readable provenance
 *
 * Simplification is documented in docs/history-data.md: Douglas–Peucker in
 * lon/lat (0.025°), coordinates quantised to 0.01° (~1.1 km at the equator),
 * tiny rings dropped and unnamed source features omitted. No border is
 * invented: every polygon comes from the upstream snapshot named by its year.
 */
import { createHash } from 'node:crypto';
import { mkdir, readFile, readdir, rm, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = fileURLToPath(new URL('..', import.meta.url));
const OUT_DIR = path.join(ROOT, 'public/data/history');
const SNAPSHOT_DIR = path.join(OUT_DIR, 'snapshots');
const CACHE_DIR = path.join(ROOT, '.cache/history');

/** Upstream revision is pinned: a rebuild cannot silently change the borders. */
export const SOURCE = Object.freeze({
  repo: 'aourednik/historical-basemaps',
  commit: 'da7a4b735ecef70aebdc9c73e409d8a2500d50f3',
  commitDate: '2026-09-15T12:38:00Z',
  title: 'Historical boundaries of world countries and cultural regions',
  provider: 'André Ourednik / historical-basemaps contributors',
  repository: 'https://github.com/aourednik/historical-basemaps',
  indexUrl: 'https://raw.githubusercontent.com/aourednik/historical-basemaps/da7a4b735ecef70aebdc9c73e409d8a2500d50f3/index.json',
  licence: 'GPL-3.0',
  licenceUrl: 'https://github.com/aourednik/historical-basemaps/blob/da7a4b735ecef70aebdc9c73e409d8a2500d50f3/LICENSE',
});

const SIMPLIFY = Object.freeze({
  toleranceDegrees: 0.025,
  coordinateDecimals: 2,
  minOuterRingArea: 0.002,
  minHoleArea: 0.0005,
  method: 'Douglas–Peucker per ring in EPSG:4326; quantise to 0.01°; drop unnamed source features and rings below the stated area',
});

const USER_AGENT = 'MeridianAtlas/0.1 (historical-borders data pipeline; +https://github.com/igor-makarov/maps-n-stuff)';
const args = new Set(process.argv.slice(2));
const offline = args.has('--offline');
const quiet = args.has('--quiet');

const log = (...parts) => {
  if (!quiet) console.log(...parts);
};

/* ---------------------------------------------------------------- geometry */

export function ringArea(ring) {
  let sum = 0;
  for (let i = 0; i < ring.length; i += 1) {
    const [x1, y1] = ring[i];
    const [x2, y2] = ring[(i + 1) % ring.length];
    sum += x1 * y2 - x2 * y1;
  }
  return Math.abs(sum) / 2;
}

export function ringBbox(ring) {
  let west = Infinity;
  let south = Infinity;
  let east = -Infinity;
  let north = -Infinity;
  for (const [lon, lat] of ring) {
    if (lon < west) west = lon;
    if (lon > east) east = lon;
    if (lat < south) south = lat;
    if (lat > north) north = lat;
  }
  return { west, south, east, north };
}

/** Point-in-polygon (ray casting), boundary counts as inside. */
export function pointInRing([x, y], ring) {
  let inside = false;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i, i += 1) {
    const [xi, yi] = ring[i];
    const [xj, yj] = ring[j];
    const intersect = yi > y !== yj > y && x < ((xj - xi) * (y - yi)) / (yj - yi) + xi;
    if (intersect) inside = !inside;
  }
  return inside;
}

/** Area-weighted centroid of a ring. */
export function ringCentroid(ring) {
  let area = 0;
  let cx = 0;
  let cy = 0;
  for (let i = 0; i < ring.length; i += 1) {
    const [x1, y1] = ring[i];
    const [x2, y2] = ring[(i + 1) % ring.length];
    const cross = x1 * y2 - x2 * y1;
    area += cross;
    cx += (x1 + x2) * cross;
    cy += (y1 + y2) * cross;
  }
  if (area === 0) {
    const n = ring.length || 1;
    return [ring.reduce((s, p) => s + p[0], 0) / n, ring.reduce((s, p) => s + p[1], 0) / n];
  }
  return [cx / (3 * area), cy / (3 * area)];
}

/**
 * A label point that is actually inside the largest ring. Centroids of concave
 * or crescent-shaped historical polities are often outside the polygon, which
 * would put a label in a neighbouring country; fall back to a grid scan.
 */
export function interiorPoint(ring) {
  const candidates = [ringCentroid(ring), [(ringBbox(ring).west + ringBbox(ring).east) / 2, (ringBbox(ring).south + ringBbox(ring).north) / 2]];
  for (const point of candidates) if (pointInRing(point, ring)) return point;
  const box = ringBbox(ring);
  for (let rows = 8; rows <= 48; rows *= 2) {
    for (let iy = 1; iy < rows; iy += 1) {
      for (let ix = 1; ix < rows; ix += 1) {
        const point = [box.west + ((box.east - box.west) * ix) / rows, box.south + ((box.north - box.south) * iy) / rows];
        if (pointInRing(point, ring)) return point;
      }
    }
  }
  return ring[0];
}

function sqSegDist(p, a, b) {
  let x = a[0];
  let y = a[1];
  let dx = b[0] - x;
  let dy = b[1] - y;
  if (dx !== 0 || dy !== 0) {
    const t = ((p[0] - x) * dx + (p[1] - y) * dy) / (dx * dx + dy * dy);
    if (t > 1) {
      x = b[0];
      y = b[1];
    } else if (t > 0) {
      x += dx * t;
      y += dy * t;
    }
  }
  dx = p[0] - x;
  dy = p[1] - y;
  return dx * dx + dy * dy;
}

function simplifyDp(points, tolerance) {
  if (points.length <= 2) return points.slice();
  const sqTolerance = tolerance * tolerance;
  const keep = new Uint8Array(points.length);
  keep[0] = 1;
  keep[points.length - 1] = 1;
  const stack = [[0, points.length - 1]];
  while (stack.length) {
    const [first, last] = stack.pop();
    let maxSq = sqTolerance;
    let index = -1;
    for (let i = first + 1; i < last; i += 1) {
      const sq = sqSegDist(points[i], points[first], points[last]);
      if (sq > maxSq) {
        index = i;
        maxSq = sq;
      }
    }
    if (index !== -1) {
      keep[index] = 1;
      stack.push([first, index], [index, last]);
    }
  }
  return points.filter((_, i) => keep[i]);
}

const quantise = (value) => Math.round(value * 10 ** SIMPLIFY.coordinateDecimals) / 10 ** SIMPLIFY.coordinateDecimals;

/** Simplify one GeoJSON ring; `null` means "too small / degenerate, drop it". */
export function simplifyRing(ring, tolerance, minArea) {
  if (!Array.isArray(ring) || ring.length < 3) return null;
  const closed = ring.length > 3 && ring[0][0] === ring[ring.length - 1][0] && ring[0][1] === ring[ring.length - 1][1];
  const body = [];
  for (const point of closed ? ring.slice(0, -1) : ring) {
    if (!Array.isArray(point) || point.length < 2 || !Number.isFinite(point[0]) || !Number.isFinite(point[1])) continue;
    const prev = body[body.length - 1];
    if (!prev || prev[0] !== point[0] || prev[1] !== point[1]) body.push([point[0], point[1]]);
  }
  if (body.length < 3) return null;
  let simple = simplifyDp(body, tolerance);
  if (simple.length < 3) simple = body;
  let quantised = [];
  for (const [lon, lat] of simple) {
    const point = [quantise(lon), quantise(lat)];
    const prev = quantised[quantised.length - 1];
    if (!prev || prev[0] !== point[0] || prev[1] !== point[1]) quantised.push(point);
  }
  if (quantised.length < 3) quantised = body.map(([lon, lat]) => [quantise(lon), quantise(lat)]);
  if (quantised.length < 3) return null;
  quantised.push([quantised[0][0], quantised[0][1]]);
  if (ringArea(quantised) < minArea) return null;
  return quantised;
}

const slug = (value) =>
  String(value)
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 72) || 'polity';

/**
 * Turn one upstream Feature into the compact, clickable shape the History UI
 * consumes. Returns null for a feature without a published NAME (the source
 * uses those for oceans/unclaimed geometry; they cannot be labelled or cited
 * as a polity, so they are omitted rather than invented).
 */
export function compactFeature(feature, usedIds) {
  const props = feature?.properties ?? {};
  const name = String(props.NAME ?? '').trim();
  if (!name) return null;
  const geometry = feature.geometry;
  if (!geometry) return null;
  const polygons = geometry.type === 'MultiPolygon' ? geometry.coordinates : geometry.type === 'Polygon' ? [geometry.coordinates] : [];
  const compact = [];
  let area = 0;
  let largest = null;
  let largestArea = -1;
  for (const polygon of polygons) {
    if (!Array.isArray(polygon) || polygon.length === 0) continue;
    const outer = simplifyRing(polygon[0], SIMPLIFY.toleranceDegrees, SIMPLIFY.minOuterRingArea);
    if (!outer) continue;
    const rings = [outer];
    for (const hole of polygon.slice(1)) {
      const simplified = simplifyRing(hole, SIMPLIFY.toleranceDegrees * 0.5, SIMPLIFY.minHoleArea);
      if (simplified) rings.push(simplified);
    }
    compact.push(rings);
    const ringAreaValue = ringArea(outer);
    area += ringAreaValue;
    if (ringAreaValue > largestArea) {
      largestArea = ringAreaValue;
      largest = outer;
    }
  }
  if (!compact.length || !largest) return null;
