  return {
    type: 'Feature',
    properties: {
      id,
      name,
      subjectTo: String(props.SUBJECTO ?? '').trim() || name,
      partOf: String(props.PARTOF ?? '').trim(),
      precision,
      area: Math.round(area * 1000) / 1000,
      label: [quantise(label[0]), quantise(label[1])],
    },
    geometry: { type: 'MultiPolygon', coordinates: compact },
  };
}

/* ------------------------------------------------------------------ build */

export function buildSnapshot(upstream, year) {
  const usedIds = new Set();
  const features = [];
  let droppedUnnamed = 0;
  for (const feature of upstream.features ?? []) {
    if (!String(feature?.properties?.NAME ?? '').trim()) {
      droppedUnnamed += 1;
      continue;
    }
    const compact = compactFeature(feature, usedIds);
    if (compact) features.push(compact);
  }
  features.sort((a, b) => b.properties.area - a.properties.area || a.properties.name.localeCompare(b.properties.name, 'en'));
  return {
    type: 'FeatureCollection',
    year,
    source: {
      repository: SOURCE.repository,
      commit: SOURCE.commit,
      licence: SOURCE.licence,
    },
    stats: { features: features.length, droppedUnnamed },
    features,
  };
}

async function fetchText(url, cacheName) {
  const cachePath = path.join(CACHE_DIR, cacheName);
  if (offline) return readFile(cachePath, 'utf8');
  try {
    const res = await fetch(url, { headers: { 'user-agent': USER_AGENT, accept: 'application/json, text/plain, */*' }, redirect: 'follow' });
    if (!res.ok) throw new Error(`HTTP ${res.status} for ${url}`);
    const text = await res.text();
    await mkdir(path.dirname(cachePath), { recursive: true });
    await writeFile(cachePath, text);
    return text;
  } catch (error) {
    try {
      const cached = await readFile(cachePath, 'utf8');
      log(`! ${url}: ${error.message}; using cached copy`);
      return cached;
    } catch {
      throw error;
    }
  }
}

const formatYear = (year) => (year < 0 ? `${Math.abs(year).toLocaleString('en-US')} BCE` : `${year.toLocaleString('en-US')} CE`);

export function buildIndex(entries, { retrievedAt }) {
  const years = entries.map((entry) => entry.year);
  const gaps = [];
  for (let i = 1; i < years.length; i += 1) {
    gaps.push({ after: years[i - 1], before: years[i], years: years[i] - years[i - 1] });
  }
  return {
    schemaVersion: 1,
    mode: 'historical-borders',
    dataset: SOURCE.title,
    provider: SOURCE.provider,
    repository: SOURCE.repository,
    commit: SOURCE.commit,
    commitDate: SOURCE.commitDate,
    licence: SOURCE.licence,
    licenceUrl: SOURCE.licenceUrl,
    sourceIndexUrl: SOURCE.indexUrl,
    retrievedAt,
    attribution: `Historical borders: ${SOURCE.provider} (${SOURCE.repository}), ${SOURCE.licence}.`,
    methodology:
      'The upstream project publishes dated snapshots, not continuous year-by-year borders. The map shows the exact snapshot only when the selected year is published; otherwise it shows the nearest published snapshot and states the represented year. The source is work in progress; borders are approximate and coverage is not worldwide in every period.',
    simplification: SIMPLIFY,
    precisionLevels: {
      1: 'Approximate',
      2: 'Moderately precise',
      3: 'Determined by international law (source)',
    },
    earliestYear: years[0],
    latestYear: years[years.length - 1],
    count: years.length,
    gaps,
    snapshots: entries.map((entry) => ({
      year: entry.year,
      label: formatYear(entry.year),
      file: `/data/history/snapshots/${entry.year}.json`,
      features: entry.features,
      droppedUnnamed: entry.droppedUnnamed,
      bytes: entry.bytes,
      sha256: entry.sha256,
    })),
  };
