  if (!upstreamYears.length) throw new Error('upstream index.json has no years');
  log(`upstream index: ${upstreamYears.length} snapshots ${upstreamYears[0].year} … ${upstreamYears[upstreamYears.length - 1].year}`);
  const entries = [];
  for (const item of upstreamYears) {
