    `- **Primary record:** ${SOURCE.repository}\n` +
    `- **Pinned upstream revision:** \`${SOURCE.commit}\` (${SOURCE.commitDate})\n` +
    `- **Upstream index used:** ${SOURCE.indexUrl}\n` +
    `- **Retrieved:** ${retrievedAt}\n` +
    `- **Licence:** ${SOURCE.licence} — see \`LICENSE-GPL-3.0.txt\` and ${SOURCE.licenceUrl}\n` +
    `- **Coverage:** ${index.count} published snapshots, ${formatYear(index.earliestYear)} … ${formatYear(index.latestYear)}. Not continuous; not worldwide in every period.\n\n` +
    `## Transformation\n\n${SIMPLIFY.method}. Coordinates are quantised to ${SIMPLIFY.coordinateDecimals} decimal places; feature names, \`SUBJECTO\`, \`PARTOF\` and \`BORDERPRECISION\` are retained. Features without a published \`NAME\` (ocean/unclaimed geometry) are omitted instead of being given an invented label. The source index is used in full.\n\n` +
    `The files in this directory are a derived copy of the upstream dataset and remain under ${SOURCE.licence}. The application code is licensed separately (see the repository \`LICENSE\`).\n`;
  await writeFile(path.join(OUT_DIR, 'SOURCE.md'), sourceNote);

  // Remove snapshots that are no longer in the upstream index (only world_*).
  const keep = new Set(entries.map((entry) => `${entry.year}.json`));
  for (const file of await readdir(SNAPSHOT_DIR)) {
    if (file.endsWith('.json') && !keep.has(file)) {
      await rm(path.join(SNAPSHOT_DIR, file));
      log(`  removed stale ${file}`);
    }
  }
  const total = entries.reduce((sum, entry) => sum + entry.bytes, 0);
  log(`wrote ${entries.length} snapshots, ${(total / 1024 / 1024).toFixed(2)} MiB, index ${(Buffer.byteLength(JSON.stringify(index)) / 1024).toFixed(0)} KiB`);
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  main().catch((error) => {
    console.error(error.stack || error.message);
    process.exitCode = 1;
  });
}
