/**
 * Natural Earth projection, normalised to a [-1, 1] square, and the small
 * view helpers the History map needs. Dependency-free so the same functions run
 * in the browser and in `node --test`.
 *
 * The source geometry is EPSG:4326. We project it once into normalised world
 * coordinates and render every snapshot as one SVG group whose transform is the
 * only thing that changes while panning/zooming. Strokes keep a constant width
 * through `vector-effect="non-scaling-stroke"`.
 */

// Natural Earth 1 polynomial (Bojan Šavrič / Tom Patterson); x is in radians.
const NE = Object.freeze({
  x0: 0.8707,
  x1: -0.131979,
  x2: -0.013791,
  x3: 0.003971,
  x4: -0.001529,
  y0: 1.007226,
  y1: 0.015085,
  y2: -0.044475,
  y3: 0.028874,
  y4: -0.005916,
});

/** Largest |x| and |y| of Natural Earth at ±180°/±90°, used to normalise. */
export const NE_X_LIMIT = 2.735384723480633;
export const NE_Y_LIMIT = 1.422390506730596;

export const MIN_ZOOM = 1;
export const MAX_ZOOM = 16;

/** Project [lon, lat] (degrees) to normalised world coordinates. */
export function projectLonLat(lon, lat) {
  const lambda = (Math.max(-180, Math.min(180, Number(lon) || 0)) * Math.PI) / 180;
  const phi = (Math.max(-90, Math.min(90, Number(lat) || 0)) * Math.PI) / 180;
  const phi2 = phi * phi;
  const phi4 = phi2 * phi2;
  const x = lambda * (NE.x0 + NE.x1 * phi2 + phi4 * (NE.x2 + phi4 * (NE.x3 * phi2 + NE.x4 * phi4)));
  // SVG y grows downwards, so the sign is flipped here once.
  const y = -phi * (NE.y0 + phi2 * (NE.y1 + phi4 * (NE.y2 + NE.y3 * phi2 + NE.y4 * phi4)));
  return [x / NE_X_LIMIT, y / NE_Y_LIMIT];
}

/** Inverse of projectLonLat. Latitude is solved monotonically, longitude analytically. */
export function unprojectLonLat(x, y) {
  const nx = Math.max(-NE_X_LIMIT, Math.min(NE_X_LIMIT, (Number(x) || 0) * NE_X_LIMIT));
  const ny = Math.max(-NE_Y_LIMIT, Math.min(NE_Y_LIMIT, -(Number(y) || 0) * NE_Y_LIMIT));
  let lo = -Math.PI / 2;
  let hi = Math.PI / 2;
  for (let i = 0; i < 60; i += 1) {
    const mid = (lo + hi) / 2;
    const mid2 = mid * mid;
    const mid4 = mid2 * mid2;
    const projected = mid * (NE.y0 + mid2 * (NE.y1 + mid4 * (NE.y2 + NE.y3 * mid2 + NE.y4 * mid4)));
    if (projected < ny) lo = mid;
    else hi = mid;
  }
  const phi = (lo + hi) / 2;
  const phi2 = phi * phi;
  const phi4 = phi2 * phi2;
  const factor = NE.x0 + NE.x1 * phi2 + NE.x4 * 0 + phi4 * (NE.x2 + phi4 * (NE.x3 * phi2 + NE.x4 * phi4));
  const lambda = Math.abs(factor) < 1e-9 ? 0 : nx / factor;
  return [Math.max(-180, Math.min(180, (lambda * 180) / Math.PI)), (phi * 180) / Math.PI];
}

export const DEFAULT_CENTER = Object.freeze({ lon: 8, lat: 24 });
export const DEFAULT_ZOOM = 1;

/**
 * Base scale for a container: the normalised world is 2 × 2. A little padding
 * keeps the outermost labels and coastlines off the rounded frame.
 */
export function baseScale(size, padding = 12) {
  const width = Math.max(1, Number(size?.width) || 1);
  const height = Math.max(1, Number(size?.height) || 1);
  return Math.min((width - padding * 2) / 2, (height - padding * 2) / 2);
}

export function clampView(view) {
  const zoom = Math.max(MIN_ZOOM, Math.min(MAX_ZOOM, Number(view?.zoom) || DEFAULT_ZOOM));
  let lon = Number(view?.lon);
  let lat = Number(view?.lat);
  if (!Number.isFinite(lon)) lon = DEFAULT_CENTER.lon;
  if (!Number.isFinite(lat)) lat = DEFAULT_CENTER.lat;
  // Keep at least a sliver of geography under the viewport: at zoom 1 the whole
  // world fits, so there is deliberately no room to pan into empty space.
  const maxLat = 82 / zoom ** 0.25;
  return {
    zoom,
    lon: Math.max(-180, Math.min(180, lon)),
    lat: Math.max(-maxLat, Math.min(maxLat, lat)),
  };
}

/** Screen position of one lon/lat under a view. */
export function screenPoint(lon, lat, view, size) {
  const [wx, wy] = projectLonLat(lon, lat);
  const [cx, cy] = projectLonLat(view.lon, view.lat);
  const scale = baseScale(size) * view.zoom;
  const width = Math.max(1, Number(size?.width) || 1);
  const height = Math.max(1, Number(size?.height) || 1);
  return [width / 2 + (wx - cx) * scale, height / 2 + (wy - cy) * scale];
}

/** SVG group transform (world coordinates -> screen pixels). */
export function viewTransform(view, size) {
  const [cx, cy] = projectLonLat(view.lon, view.lat);
  const scale = baseScale(size) * view.zoom;
  const width = Math.max(1, Number(size?.width) || 1);
  const height = Math.max(1, Number(size?.height) || 1);
  return { translateX: width / 2 - cx * scale, translateY: height / 2 - cy * scale, scale };
}

/** Geographic point at a screen position (used for click-zoom and drag panning). */
export function pointToLonLat(x, y, view, size) {
  const [cx, cy] = projectLonLat(view.lon, view.lat);
  const scale = baseScale(size) * view.zoom;
  const width = Math.max(1, Number(size?.width) || 1);
  const height = Math.max(1, Number(size?.height) || 1);
  return unprojectLonLat(cx + (x - width / 2) / scale, cy + (y - height / 2) / scale);
}

/** Drag by `dx`,`dy` screen pixels; the content follows the pointer. */
export function panView(view, dx, dy, size) {
  const [lon, lat] = pointToLonLat((size?.width || 1) / 2 - dx, (size?.height || 1) / 2 - dy, view, size);
  return clampView({ ...view, lon, lat });
}

/** Zoom around a screen anchor, keeping the geography under the pointer. */
export function zoomView(view, factor, anchor, size) {
  const nextZoom = Math.max(MIN_ZOOM, Math.min(MAX_ZOOM, view.zoom * factor));
  if (nextZoom === view.zoom) return { ...view };
  const width = Math.max(1, Number(size?.width) || 1);
  const height = Math.max(1, Number(size?.height) || 1);
  const [wx, wy] = projectLonLat(view.lon, view.lat);
  const oldScale = baseScale(size) * view.zoom;
  const nextScale = baseScale(size) * nextZoom;
  const point = anchor ?? [width / 2, height / 2];
  const geo = unprojectLonLat(wx + (point[0] - width / 2) / oldScale, wy + (point[1] - height / 2) / oldScale);
  const [gx, gy] = projectLonLat(geo[0], geo[1]);
  const cx = gx - (point[0] - width / 2) / nextScale;
  const cy = gy - (point[1] - height / 2) / nextScale;
  const [lon, lat] = unprojectLonLat(cx, cy);
  return clampView({ lon, lat, zoom: nextZoom });
}

/** Bounds of one normalised ring in world coordinates. */
export function ringWorldBbox(ring) {
  let west = Infinity;
  let south = Infinity;
  let east = -Infinity;
  let north = -Infinity;
  for (const [lon, lat] of ring) {
    const [x, y] = projectLonLat(lon, lat);
    if (x < west) west = x;
    if (x > east) east = x;
    if (y < south) south = y;
    if (y > north) north = y;
  }
  return { west, south, east, north };
}

/**
 * Fit one feature's geometry into the viewport (used by “Zoom to this polity”).
 * A minimum span keeps a tiny island from zooming to the maximum.
 */
export function fitFeature(feature, size, { padding = 60, maxZoom = 7, minSpan = 0.02 } = {}) {
  let west = Infinity;
  let south = Infinity;
  let east = -Infinity;
  let north = -Infinity;
  const polygons = feature?.geometry?.coordinates ?? [];
  for (const polygon of polygons) {
    for (const ring of polygon) {
      const box = ringWorldBbox(ring);
      west = Math.min(west, box.west);
      east = Math.max(east, box.east);
      south = Math.min(south, box.south);
      north = Math.max(north, box.north);
    }
  }
  if (!Number.isFinite(west)) return null;
  const spanX = Math.max(minSpan, east - west);
  const spanY = Math.max(minSpan, north - south);
  const width = Math.max(1, Number(size?.width) || 1);
  const height = Math.max(1, Number(size?.height) || 1);
  const zoom = Math.max(MIN_ZOOM, Math.min(maxZoom, Math.min((width - padding * 2) / (spanX * baseScale(size)), (height - padding * 2) / (spanY * baseScale(size)))));
  const [lon, lat] = unprojectLonLat((west + east) / 2, (south + north) / 2);
  return clampView({ lon, lat, zoom });
}
