/**
 * Pure model helpers for the History / Borders view: year formatting, honest
 * nearest-snapshot selection, URL state, colours and label layout. No DOM, so
 * every rule is unit-tested in node.
 */

export const MODE = 'borders';
export const DEFAULT_YEAR = 1500;
export const DEFAULT_VIEW = Object.freeze({ lon: 8, lat: 24, zoom: 1 });
export const LABELS_PARAM = 'labels';

const NUMBER = new Intl.NumberFormat('en-US');

/** “1500 CE”, “500 BCE”, “123,000 BCE”. Year 0 is avoided (there is no year 0). */
export function formatYear(year) {
  const value = Math.trunc(Number(year) || 0);
  if (value < 0) return `${NUMBER.format(Math.abs(value))} BCE`;
  return `${NUMBER.format(value)} CE`;
}

/** Short form for tight controls: “1500” or “500 BCE”. */
export function formatYearShort(year) {
  const value = Math.trunc(Number(year) || 0);
  if (value < 0) return `${NUMBER.format(Math.abs(value))} BCE`;
  return NUMBER.format(value);
}

/** Year input is positive with an explicit era; negative years are accepted too. */
export function parseYearInput(input, era = 'ce') {
  const raw = String(input ?? '').trim().replace(/,/g, '');
  if (!/^-?\d{1,6}$/.test(raw)) return null;
  const value = Number(raw);
  if (!Number.isInteger(value) || value === 0) return null;
  if (value < 0) return value;
  return String(era).toLowerCase() === 'bce' ? -value : value;
}

/**
 * The source publishes discrete snapshots. Never invent an intermediate year:
 * return the closest published snapshot and say which way it lies.
 */
export function nearestSnapshot(year, snapshots) {
  const list = (snapshots ?? [])
    .map((item) => (typeof item === 'number' ? { year: item } : item))
    .filter((item) => Number.isInteger(item?.year))
    .sort((a, b) => a.year - b.year);
  if (!list.length) return null;
  const wanted = Math.trunc(Number(year));
  if (!Number.isFinite(wanted)) {
    return { snapshot: list[0], exact: false, distance: Infinity, direction: 'after-range' };
  }
  const exact = list.find((item) => item.year === wanted);
  if (exact) return { snapshot: exact, exact: true, distance: 0, direction: 'exact' };
  if (wanted < list[0].year) return { snapshot: list[0], exact: false, distance: list[0].year - wanted, direction: 'before-range' };
  if (wanted > list[list.length - 1].year) {
    const last = list[list.length - 1];
    return { snapshot: last, exact: false, distance: wanted - last.year, direction: 'after-range' };
  }
  let before = list[0];
  let after = list[list.length - 1];
  for (const item of list) {
    if (item.year <= wanted) before = item;
    if (item.year >= wanted) {
      after = item;
      break;
    }
  }
  // Ties resolve to the earlier snapshot: it cannot claim to know a later border.
  if (wanted - before.year <= after.year - wanted) {
    return { snapshot: before, exact: false, distance: wanted - before.year, direction: 'earlier' };
  }
  return { snapshot: after, exact: false, distance: after.year - wanted, direction: 'later' };
}

/** Neighbouring snapshots and the gap that contains `year` (for the honest note). */
export function snapshotNeighbours(year, snapshots) {
  const list = [...(snapshots ?? [])].filter((item) => Number.isInteger(item?.year)).sort((a, b) => a.year - b.year);
  if (!list.length) return { previous: null, next: null };
  let previous = null;
  let next = null;
  for (const item of list) {
    if (item.year <= year) previous = item;
    if (item.year > year) {
      next = item;
      break;
    }
  }
  return { previous, next };
}

/** Human sentence for the nearest-snapshot notice. */
export function representedNotice(year, snapshots) {
  const result = nearestSnapshot(year, snapshots);
  if (!result) return { text: 'No snapshots available.', exact: false, snapshot: null, requestedYear: year };
  const snapshotYear = result.snapshot.year;
  const requested = Number(year);
  if (result.exact) {
    return {
      text: `Exact published snapshot for ${formatYear(requested)}.`,
      exact: true,
      snapshot: result.snapshot,
      requestedYear: requested,
    };
  }
  const years = NUMBER.format(result.distance);
  const gap = snapshotNeighbours(snapshotYear, snapshots);
  let relation;
  if (result.direction === 'before-range') relation = `The source's earliest snapshot is ${formatYear(snapshotYear)}; nothing earlier is published.`;
  else if (result.direction === 'after-range') relation = `The source's latest snapshot is ${formatYear(snapshotYear)}; nothing later is published.`;
  else if (result.direction === 'earlier') relation = `${formatYear(snapshotYear)} is ${years} year${result.distance === 1 ? '' : 's'} earlier than ${formatYear(requested)}.`;
  else relation = `${formatYear(snapshotYear)} is ${years} year${result.distance === 1 ? '' : 's'} later than ${formatYear(requested)}.`;
  const span = gap.previous && gap.next ? ` Published neighbours: ${formatYear(gap.previous.year)} and ${formatYear(gap.next.year)}.` : '';
  return {
    text: `Showing the nearest published snapshot, ${formatYear(snapshotYear)}. ${relation}${span}`,
    exact: false,
    snapshot: result.snapshot,
    requestedYear: requested,
    distance: result.distance,
    direction: result.direction,
    previous: gap.previous,
    next: gap.next,
  };
}

/** Curated muted atlas palette; colours group the source's SUBJECTO values. */
export const PALETTE = Object.freeze([
  '#a9b79b',
  '#c9a26f',
  '#9db3c2',
  '#c69b87',
  '#b3a5c2',
  '#c7bd85',
  '#8fa892',
  '#b9a08c',
  '#8ea9b4',
  '#c1ae74',
  '#ac9cba',
  '#9bb2a1',
  '#cda98e',
  '#8fa0b8',
]);

export function colorFor(name) {
  let hash = 2166136261;
  for (const char of String(name ?? '')) {
    hash ^= char.codePointAt(0);
    hash = Math.imul(hash, 16777619);
  }
  return PALETTE[Math.abs(hash) % PALETTE.length];
}

export function precisionLabel(precision) {
  if (Number(precision) === 3) return 'Determined by international law (source value 3)';
  if (Number(precision) === 2) return 'Moderately precise (source value 2)';
  return 'Approximate (source value 1)';
}

export function precisionShort(precision) {
  if (Number(precision) === 3) return 'Legal';
  if (Number(precision) === 2) return 'Moderate';
  return 'Approximate';
}

/**
 * Parse a history URL. Unknown/hand-edited values never crash the page: the
 * page falls back to a published nearest snapshot and the documented view.
 */
export function parseHistoryState(search, snapshots, defaults = {}) {
  const params = new URLSearchParams(String(search ?? ''));
  const defaultView = { ...DEFAULT_VIEW, ...(defaults.view ?? {}) };
  const rawYear = params.get('year');
  const parsedYear = rawYear === null || rawYear.trim() === '' ? NaN : Number(rawYear);
  const requestedYear = Number.isFinite(parsedYear) ? Math.trunc(parsedYear) : defaults.year ?? DEFAULT_YEAR;
  const represented = nearestSnapshot(requestedYear, snapshots);
  const snapshotYear = represented?.snapshot?.year ?? defaults.year ?? DEFAULT_YEAR;
  const lat = Number(params.get('lat'));
  const lon = Number(params.get('lon'));
  const zoom = Number(params.get('zoom'));
  const labels = params.get(LABELS_PARAM) !== '0';
  const selectedId = (params.get('polity') ?? '').trim();
  return {
    mode: MODE,
    requestedYear,
    snapshotYear,
    exact: Boolean(represented?.exact),
    direction: represented?.direction ?? 'exact',
    distance: represented?.distance ?? 0,
    lon: Number.isFinite(lon) ? Math.max(-180, Math.min(180, lon)) : defaultView.lon,
    lat: Number.isFinite(lat) ? Math.max(-82, Math.min(82, lat)) : defaultView.lat,
    zoom: Number.isFinite(zoom) ? Math.max(1, Math.min(16, zoom)) : defaultView.zoom,
    selectedId,
    labels,
  };
}

/** Write only non-default, shareable state; `mode=borders` names the view. */
export function serializeHistoryState(state, defaults = {}) {
  const params = new URLSearchParams();
  params.set('mode', MODE);
  params.set('year', String(Math.trunc(Number(state.snapshotYear))));
  const defaultView = { ...DEFAULT_VIEW, ...(defaults.view ?? {}) };
  const lon = Math.round(Number(state.lon) * 100) / 100;
  const lat = Math.round(Number(state.lat) * 100) / 100;
  const zoom = Math.round(Number(state.zoom) * 100) / 100;
  if (Math.abs(lon - defaultView.lon) >= 0.01) params.set('lon', String(lon));
  if (Math.abs(lat - defaultView.lat) >= 0.01) params.set('lat', String(lat));
  if (Math.abs(zoom - defaultView.zoom) >= 0.01) params.set('zoom', String(zoom));
  if (state.selectedId) params.set('polity', String(state.selectedId));
  if (state.labels === false) params.set(LABELS_PARAM, '0');
  return params.toString();
}

export function polityById(features, id) {
  if (!id) return null;
  return (features ?? []).find((feature) => feature?.properties?.id === id) ?? null;
}

/**
 * Greedy, deterministic label placement in screen space. Labels never overlap
 * each other; at world scale only the largest polities receive one. The
 * selected polity is always placed first.
 */
export function layoutLabels(features, view, size, { maxLabels = 30, selectedId = '' } = {}) {
  const width = Math.max(1, Number(size?.width) || 1);
  const height = Math.max(1, Number(size?.height) || 1);
  const sorted = [...(features ?? [])]
    .filter((feature) => Array.isArray(feature?.properties?.label) && feature.properties.name)
    .sort((a, b) => {
      if (a.properties.id === selectedId) return -1;
      if (b.properties.id === selectedId) return 1;
      return Number(b.properties.area || 0) - Number(a.properties.area || 0);
    });
  const placed = [];
  const result = [];
  const occupied = [];
  const overlaps = (rect) => occupied.some((other) => rect.x < other.x + other.w && rect.x + rect.w > other.x && rect.y < other.y + other.h && rect.y + rect.h > other.y);
  for (const feature of sorted) {
    if (result.length >= maxLabels) break;
    const [lon, lat] = feature.properties.label;
    const [x, y] = projectLabel(lon, lat, view, size);
    if (!Number.isFinite(x) || !Number.isFinite(y)) continue;
    if (x < 18 || x > width - 18 || y < 14 || y > height - 14) continue;
    const rank = result.length;
    const fontSize = feature.properties.id === selectedId ? 13 : rank < 3 ? 12.5 : rank < 9 ? 11.5 : 10.5;
    const name = String(feature.properties.name);
    const w = Math.min(name.length * fontSize * 0.54 + 8, width - 24);
    const h = fontSize + 4;
    const rect = { x: x - w / 2, y: y - h / 2, w, h };
    if (overlaps(rect)) continue;
    occupied.push(rect);
    placed.push(feature.properties.id);
    result.push({ feature, x, y, fontSize, rect });
  }
  return result;
}

// Imported lazily here to keep the model's public surface obvious while still
// avoiding a second implementation of the projection in the label layout.
import { screenPoint } from './projection.js';

function projectLabel(lon, lat, view, size) {
  return screenPoint(lon, lat, view, size);
}
EOF
