  --ma-ink-strong: #0d2235;
  --ma-ink-soft: #3b5062;
  --ma-paper: #f4efe4;
  --ma-paper-deep: #e9e1d2;
  --ma-surface: #fffdf8;
  --ma-line: #d3c8b5;
  --ma-line-strong: #a99d89;
