  --ma-brass-soft: #f0e2c4;
  --ma-rust: #9a4f35;
  --ma-rust-soft: #f2ded4;
  --ma-focus: #1f6f78;
  --ma-ocean: #e7dfcf;
  --ma-shadow: 0 1px 2px rgb(22 50 76 / 8%), 0 10px 28px rgb(22 50 76 / 7%);
  --ma-radius: 2px;
  --ma-max: 1440px;
  --ma-font: 'InterRegular', 'Inter', Helvetica, Arial, sans-serif;
  --ma-font-black: 'InterBlack', 'Inter', 'Arial Black', Helvetica, sans-serif;
}

.hx-body {
  margin: 0;
  background:
    radial-gradient(1200px 500px at 12% -8%, rgb(176 126 46 / 7%), transparent 70%),
    var(--ma-paper);
  color: var(--ma-ink);
  font-family: var(--ma-font);
  font-size: 16px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

.hx-body *,
.hx-body *::before,
.hx-body *::after {
  box-sizing: border-box;
}

.hx-body [hidden] {
  display: none !important;
}

.hx-shell {
  width: min(100% - 40px, var(--ma-max));
  margin-inline: auto;
}

.hx-body :focus-visible {
  outline: 3px solid var(--ma-focus);
  outline-offset: 2px;
}

.hx-body a {
