}

.hx-map {
  display: block;
  width: 100%;
  height: 100%;
  overflow: hidden;
  outline: none;
  user-select: none;
}

.hx-map:focus-visible {
  outline: 3px solid var(--ma-focus);
  outline-offset: -3px;
}

.hx-graticule path {
  fill: none;
  stroke: rgb(22 50 76 / 16%);
  stroke-width: 0.7;
  vector-effect: non-scaling-stroke;
}

.hx-graticule path[data-equator='true'] {
