  stroke-width: 1.8;
}

.hx-features path[data-selected='true'] {
  stroke: var(--ma-focus);
  stroke-width: 2.4;
  stroke-dasharray: none;
  fill-opacity: 1;
}

.hx-labels text {
  fill: #152936;
  font-family: var(--ma-font);
  font-weight: 700;
  letter-spacing: 0.005em;
  paint-order: stroke;
  stroke: rgb(244 239 228 / 88%);
  stroke-width: 3px;
  stroke-linejoin: round;
  pointer-events: none;
}

.hx-labels text[data-selected='true'] {
  fill: var(--ma-focus);
  stroke: #fffdf8;
  stroke-width: 3.5px;
}

.hx-map-loading {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  background: rgb(244 239 228 / 82%);
  color: var(--ma-ink-soft);
  font-size: 14px;
  z-index: 4;
}

.hx-spinner {
  width: 22px;
  height: 22px;
  border: 2px solid rgb(22 50 76 / 20%);
  border-top-color: var(--ma-rust);
  border-radius: 50%;
  animation: hx-spin 900ms linear infinite;
}

@keyframes hx-spin {
  to {
    transform: rotate(360deg);
  }
}

@media (prefers-reduced-motion: reduce) {
  .hx-spinner {
    animation-duration: 3s;
  }
  .hx-features path {
    transition: none;
  }
}

.hx-map-status {
  position: absolute;
  top: 12px;
  left: 12px;
  max-width: min(420px, calc(100% - 24px));
  padding: 8px 10px;
  border-left: 3px solid var(--ma-rust);
  background: rgb(255 253 248 / 94%);
  color: #592919;
  font-size: 13px;
  line-height: 1.4;
  box-shadow: var(--ma-shadow);
  z-index: 3;
}

.hx-map-status:empty {
  display: none;
}

.hx-map-status a {
  color: inherit;
}

.hx-legend {
  position: absolute;
  left: 12px;
  bottom: 12px;
  display: flex;
  flex-wrap: wrap;
  gap: 8px 12px;
  max-width: calc(100% - 24px);
  padding: 7px 9px;
  background: rgb(255 253 248 / 92%);
  border: 1px solid var(--ma-line);
  color: var(--ma-ink-soft);
  font-size: 11px;
  z-index: 2;
}

.hx-legend__item {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

.hx-swatch {
  display: inline-block;
  width: 18px;
  height: 10px;
  background: #a9b79b;
  border: 1px solid rgb(22 50 76 / 75%);
}

.hx-swatch--solid {
  background: #a9b79b;
  border-style: solid;
}

.hx-swatch--dashed {
  background: #c9a26f;
  border-style: dashed;
}

.hx-swatch--blue {
  background: #fffdf8;
  border: 2px solid var(--ma-focus);
}

.hx-map-caveat {
  position: absolute;
  right: 12px;
  bottom: 12px;
  max-width: 300px;
  margin: 0;
  padding: 5px 7px;
  background: rgb(255 253 248 / 86%);
  color: var(--ma-muted);
  font-size: 10px;
  line-height: 1.3;
  text-align: right;
  z-index: 2;
}

/* ------------------------------------------------------------------- side */

.hx-side {
  display: flex;
  flex-direction: column;
  gap: 16px;
  min-width: 0;
}

.hx-detail,
.hx-finder {
  padding: 18px;
}

.hx-detail h2,
.hx-finder h2 {
  font-size: 21px;
  line-height: 1.15;
}

.hx-detail p {
  color: var(--ma-ink-soft);
  font-size: 14px;
}

.hx-detail .hx-eyebrow {
  margin-bottom: 6px;
  font-size: 10px;
}

.hx-detail-meta {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1px;
  margin: 14px 0;
  background: var(--ma-line);
  border: 1px solid var(--ma-line);
}

.hx-detail-meta > div {
  padding: 8px 10px;
  background: var(--ma-surface);
}

.hx-detail-meta dt {
  color: var(--ma-muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.hx-detail-meta dd {
  margin: 2px 0 0;
  font-size: 14px;
  line-height: 1.4;
  overflow-wrap: anywhere;
}

.hx-detail-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 12px;
}

.hx-detail-actions .hx-button {
  min-height: 40px;
  font-size: 14px;
}

.hx-detail-note {
  margin: 12px 0 0;
  padding: 9px 10px;
  background: var(--ma-paper);
  border-left: 3px solid var(--ma-brass);
  color: var(--ma-ink-soft);
  font-size: 12px;
  line-height: 1.45;
}

.hx-detail-source {
  margin: 12px 0 0;
  font-size: 12px;
  color: var(--ma-muted);
}

.hx-polity-count {
  margin: 8px 0;
  color: var(--ma-muted);
  font-size: 12px;
}

.hx-polity-list {
  list-style: none;
  margin: 0;
  padding: 0;
  max-height: 380px;
  overflow-y: auto;
  border-top: 1px solid var(--ma-line);
}

.hx-polity-list li {
  border-bottom: 1px solid var(--ma-line);
}

.hx-polity-button {
  display: grid;
  grid-template-columns: 10px minmax(0, 1fr) auto;
  align-items: center;
  gap: 8px;
  width: 100%;
  min-height: 44px;
  padding: 7px 6px;
  border: 0;
  border-left: 3px solid transparent;
  background: transparent;
  color: var(--ma-ink);
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.hx-polity-button:hover {
  background: var(--ma-paper);
}

.hx-polity-button[aria-pressed='true'] {
  border-left-color: var(--ma-focus);
  background: #e8eff0;
}

.hx-polity-dot {
  width: 10px;
  height: 10px;
  border: 1px solid rgb(22 50 76 / 45%);
  border-radius: 50%;
}

.hx-polity-name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 14px;
}

.hx-polity-meta {
  color: var(--ma-muted);
  font-size: 10px;
  white-space: nowrap;
}

.hx-polity-empty {
  padding: 12px 6px;
  color: var(--ma-muted);
  font-size: 13px;
}

/* ---------------------------------------------------------------- sources */

.hx-sources {
  margin-top: 40px;
  padding-top: 24px;
  border-top: 2px solid var(--ma-ink);
  max-width: 1000px;
}

.hx-sources h2 {
  font-size: clamp(24px, 2.6vw, 34px);
  margin-bottom: 14px;
}

.hx-sources p,
.hx-sources li {
  color: var(--ma-ink-soft);
  font-size: 14px;
  line-height: 1.6;
}

.hx-sources ul {
  padding-left: 20px;
}

.hx-sources li + li {
  margin-top: 6px;
}

.hx-small {
  font-size: 12px !important;
  color: var(--ma-muted) !important;
}

/* ----------------------------------------------------------------- footer */

.hx-footer {
  border-top: 1px solid var(--ma-line);
  background: var(--ma-ink);
  color: #d9d2c2;
  margin-top: 56px;
}

.hx-footer__inner {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  padding-block: 22px;
}

.hx-footer p {
  margin: 0;
  font-size: 12px;
}

.hx-footer strong {
  color: #fff;
}

.hx-footer a {
  color: #f1e7d4;
}

.hx-footer a:hover {
  color: #fff;
}

.hx-noscript {
  margin: 20px;
  padding: 16px;
  border: 1px solid var(--ma-rust);
  background: var(--ma-rust-soft);
  color: #592919;
}

.visuallyhidden {
  position: absolute !important;
  width: 1px !important;
  height: 1px !important;
  padding: 0 !important;
  margin: -1px !important;
  overflow: hidden !important;
  clip: rect(0, 0, 0, 0) !important;
  white-space: nowrap !important;
  border: 0 !important;
}

/* -------------------------------------------------------------- responsive */

@media (max-width: 1050px) {
  .hx-hero {
    grid-template-columns: 1fr;
    align-items: start;
  }
  .hx-facts {
    max-width: 640px;
  }
  .hx-layout {
    grid-template-columns: 1fr;
  }
  .hx-side {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
    align-items: start;
  }
}

@media (max-width: 760px) {
  .hx-shell {
    width: min(100% - 24px, var(--ma-max));
  }
  .hx-header__inner {
    min-height: 64px;
    gap: 12px;
    align-items: flex-start;
    padding-block: 8px;
    flex-wrap: wrap;
  }
  .hx-brand__mark {
    width: 38px;
    height: 38px;
  }
  .hx-brand__name {
    font-size: 18px;
  }
  .hx-brand__claim {
    font-size: 10px;
  }
  .hx-nav a {
    min-height: 38px;
    padding-inline: 8px;
    font-size: 14px;
  }
  #history-main {
    padding-block: 18px 40px;
  }
  .hx-facts {
    grid-template-columns: 1fr;
  }
  .hx-facts > div {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 12px;
    padding: 10px 14px;
  }
  .hx-facts dd {
    margin: 0;
    font-size: 16px;
    text-align: right;
  }
  .hx-controls__row {
    align-items: stretch;
  }
  .hx-year-form {
    flex: 1 1 100%;
    align-items: end;
  }
  .hx-select-label {
    display: none;
  }
  .hx-select--snapshot {
    flex: 1 1 100%;
  }
  .hx-map-frame {
    height: 56vh;
    min-height: 340px;
  }
  .hx-legend {
    right: 12px;
    max-width: none;
  }
  .hx-map-caveat {
    display: none;
  }
  .hx-side {
    display: flex;
  }
  .hx-polity-list {
    max-height: 320px;
  }
  .hx-footer__inner {
    flex-direction: column;
  }
}

@media (max-width: 460px) {
  .hx-hero {
    gap: 18px;
    padding-bottom: 18px;
  }
  .hx-controls__head {
    align-items: flex-start;
    flex-direction: column;
    gap: 6px;
  }
  .hx-year-output {
    flex-wrap: wrap;
  }
  .hx-button,
  .hx-input,
  .hx-select {
    font-size: 14px;
  }
  .hx-button {
    padding-inline: 12px;
  }
  .hx-map-tools {
    gap: 4px;
  }
  .hx-panel-head {
    align-items: flex-start;
    flex-direction: column;
  }
  .hx-legend {
    font-size: 10px;
    gap: 6px 8px;
  }
  .hx-map-frame {
    height: 52vh;
    min-height: 300px;
  }
}

@media (forced-colors: active) {
  .hx-features path[data-selected='true'] {
    stroke: Highlight;
    stroke-width: 3;
  }
  .hx-labels text {
    fill: CanvasText;
    stroke: Canvas;
  }
  .hx-tick[aria-current='true'] {
    outline: 2px solid Highlight;
    outline-offset: -2px;
  }
}
